function freshState(){let a=makeRequest('ENQ-0042','Norte Industrial','email','PDF');let b=makeRequest('ENQ-0043','Lerma Metalworks','portal','Scanned PDF',true);b.original[0].desc={en:'SS hex bolt M10 - length unspecified',es:'Perno inoxidable M10 - longitud sin especificar'};let c=makeRequest('ENQ-0044','Pacific Works','manual','Text');c.original=[structuredClone(productSeeds[2])];c.original[0].qty=36;return {selected:a.id,page:'requests',fx:{OMR:1,AED:.1047,USD:.3845},minMargin:15,baseMargin:20,requests:[a,b,c],history:structuredClone(historySeeds),past:[{id:'QT-0036',customer:'Pacific Works',value:420,cost:320,outcome:'won',turnaround:3.2,cat:'safety'},{id:'QT-0037',customer:'Norte Industrial',value:685,cost:510,outcome:'lost',turnaround:4.1,cat:'hardware'},{id:'QT-0038',customer:'Lerma Metalworks',value:295,cost:219,outcome:'won',turnaround:2.5,cat:'tools'},{id:'QT-0039',customer:'Norte Industrial',value:810,cost:590,outcome:'won',turnaround:3.5,cat:'hardware'},{id:'QT-0040',customer:'Pacific Works',value:560,cost:420,outcome:'noresponse',turnaround:5.1,cat:'safety'}],activity:[],historyImported:false};}
let S;try{S=JSON.parse(localStorage.getItem(KEY))}catch{}if(!S?.requests?.length||!S.fx)S=freshState();
let requestFilter='all',reportFilter='all',toastTimer,modalTask=null;
const R=()=>S.requests.find(r=>r.id===S.selected)||S.requests[0], SUP=id=>suppliers.find(s=>s.id===id), money=(v,c='OMR')=>new Intl.NumberFormat(lang==='es'?'es-MX':'en-US',{style:'currency',currency:c,minimumFractionDigits:c==='OMR'?3:2}).format(Number(v)||0), amt=v=>Number(v||0).toFixed(3), date=d=>new Intl.DateTimeFormat(lang==='es'?'es-MX':'en-GB',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00')), valid=d=>d>=DAY;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));localStorage.setItem('zeltranet-demo-language',lang)}catch{toast(T('Browser storage unavailable. Keep this tab open.','El almacenamiento no está disponible. Mantén esta pestaña abierta.'))}}
function log(r,en,es){const e={en,es,at:new Date().toLocaleTimeString(lang==='es'?'es-MX':'en-GB',{hour:'2-digit',minute:'2-digit'}),ref:r.id};r.events.unshift(e);S.activity.unshift(e);save()}
function toast(text){$('toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',4500)}
function badge(txt,type=''){return '<span class="badge '+type+'">'+E(txt)+'</span>'}
function status(r){return r.quote?.outcome==='won'?badge(T('Order confirmed','Pedido confirmado'),'good'):r.quote?.sent?badge(T('Quote sent','Cotización enviada'),'good'):r.rfqs.some(x=>x.sent)?badge(T('Awaiting prices','Esperando precios'),'warn'):r.extracted?badge(T('Ready for review','Lista para revisión')):badge(T('New','Nueva'))}
function btn(en,es,a,id='',secondary=false){return '<button class="btn'+(secondary?' secondary':'')+'" data-action="'+a+'" data-id="'+E(id)+'">'+T(en,es)+'</button>'}
function empty(en,es,bodyEn,bodyEs,action){return '<div class="panel empty"><h2>'+T(en,es)+'</h2><p>'+T(bodyEn,bodyEs)+'</p>'+(action||'')+'</div>'}
function itemDesc(i){return E(typeof i.desc==='object'?L(i.desc):i.desc)}
function currentOffer(r,i){if(r.historyUsed[i.id])return {...r.historyUsed[i.id],history:true};return r.offers.find(o=>o.id===r.chosen[i.id]);}
function norm(o){const rate=S.fx[o.currency]||1;return o.price*rate/(o.pack||1)*(1+(o.uplift||0)/100)}
function eligible(o,i){return valid(o.valid)&&i.qty>=o.moq}
function marginFor(r,i){const o=r.overrides[i.id]||{};return o.margin??(S.baseMargin+(i.category==='safety'?5:0)+(r.type==='standard'?3:0)+(r.credit===60?3:0))}
function calcQuote(r){let lines=[];for(const i of r.items){const o=currentOffer(r,i);if(!o||r.include[i.id]===false)continue;const cost=o.history?o.cost:norm(o),margin=marginFor(r,i),override=r.overrides[i.id]||{},price=Math.round((override.price??(cost/(1-margin/100)))*1000)/1000;lines.push({...i,supplier:o.supplier,cost,price,margin:price>0?(price-cost)/price*100:0,total:price*i.qty,costTotal:cost*i.qty,valid:o.valid,offer:o});}const total=lines.reduce((a,x)=>a+x.total,0),cost=lines.reduce((a,x)=>a+x.costTotal,0);return {lines,total,cost,margin:total?(total-cost)/total*100:0,until:lines.map(x=>x.valid).sort()[0]||DAY,missing:r.items.length-lines.length};}
function rfqGroups(r){return [...new Set(r.items.filter(i=>!r.historyUsed[i.id]).map(i=>i.category))]}
function render(){ensureWhatsApp();document.documentElement.lang=lang;document.title='Zeltranet · AI Automator for Quotes and Purchasing';const pages=[['whatsapp','WhatsApp'],['requests',T('Requests','Solicitudes')],['rfqs',T('Supplier requests','Solicitudes a proveedores')],['replies',T('Replies & comparison','Respuestas y precios')],['history',T('Price history','Historial de precios')],['quotes',T('Customer quotations','Cotizaciones a clientes')],['reports',T('Orders & reports','Pedidos e informes')]];document.querySelectorAll('[data-language]').forEach(b=>b.classList.toggle('active',b.dataset.language===lang));$('nav').innerHTML=pages.map((p,i)=>'<button class="'+(S.page===p[0]?'active':'')+'" data-action="page" data-id="'+p[0]+'" '+(S.page===p[0]?'aria-current="page"':'')+'><span class="num">'+(i===0?'WA':String(i).padStart(2,'0'))+'</span>'+p[1]+'</button>').join('');$('navLabel').textContent=T('TRADING OPERATIONS','OPERACIÓN COMERCIAL');$('productSub').textContent='AI Automator for Quotes and Purchasing';$('siteLink').textContent=T('← Back to Zeltranet','← Volver a Zeltranet');$('siteLink').href=T('/work/','/es/proyectos/');$('workspaceName').textContent=T('Trading workspace','Espacio comercial');$('pageName').textContent=pages.find(p=>p[0]===S.page)[1];$('localLabel').textContent=T('Example workspace · Messages are not sent','Espacio de ejemplo · Los mensajes no se envían');$('activityBtn').textContent=T('Activity log','Registro de actividad');$('settingsBtn').textContent=T('Settings','Configuración');$('resetBtn').textContent=T('Reset workspace','Restablecer espacio de trabajo');$('exportBtn').textContent=T('Export workspace','Exportar datos');$('app').innerHTML=({whatsapp:renderWhatsApp,requests:renderRequests,rfqs:renderRFQs,replies:renderReplies,history:renderHistory,quotes:renderQuotes,reports:renderReports})[S.page]();save();}
function heading(title,sub,actions=''){return '<div class="heading"><div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="toolbar">'+actions+'</div></div>'}
