function sourceName(v){return ({whatsapp:'WhatsApp',email:T('Email','Correo'),portal:T('Customer portal','Portal del cliente'),upload:T('Upload','Archivo'),manual:T('Manual entry','Entrada manual')})[v]}
function renderRequests(){const r=R();const list=S.requests.filter(x=>requestFilter==='all'||(requestFilter==='new'?!x.extracted:x.extracted));let html=heading(T('Customer requests','Solicitudes de clientes'),T('Incoming requirements, documents and extracted products.','Requerimientos entrantes, documentos y productos extraídos.'),btn('Import request','Importar solicitud','import')+btn('Add request','Agregar solicitud','addsample','',true));html+='<div class="grid inbox"><aside><div class="toolbar u-mb14"><select data-change="requestFilter" aria-label="'+T('Filter requests','Filtrar solicitudes')+'">'+[['all',T('All requests','Todas las solicitudes')],['new',T('New','Nuevas')],['review',T('Extracted','Extraídas')]].map(x=>'<option value="'+x[0]+'" '+(x[0]===requestFilter?'selected':'')+'>'+x[1]+'</option>').join('')+'</select>'+btn('Check duplicate','Probar duplicado','duplicate','',true)+'</div><div class="requests">'+list.map(x=>'<button class="request '+(x.id===r.id?'active':'')+'" data-action="select" data-id="'+x.id+'"><div class="meta"><span>'+x.id+'</span><span>'+sourceName(x.source)+'</span></div><strong>'+E(x.customer)+'</strong><small>'+E(x.reference)+' · '+E(x.format)+' · v'+x.version+'</small><div class="u-mt11">'+status(x)+'</div></button>').join('')+'</div></aside><section><div class="panel"><div class="panel-head"><div><h2>'+E(r.customer)+'</h2><div class="meta">'+E(r.id+' / '+r.reference)+' · '+sourceName(r.source)+' · '+E(r.format)+'</div></div>'+status(r)+'</div><div class="tabs"><button class="'+(!r.extracted?'active':'')+'" data-action="source">'+T('Original request','Solicitud original')+'</button><button class="'+(r.extracted?'active':'')+'" data-action="extract">'+T('Extracted items','Productos extraídos')+(r.extracted?' ('+r.items.length+')':'')+'</button><button data-action="revision">'+T('Import revision','Importar revisión')+'</button></div>';
if(!r.extracted||r.showOriginal){html+='<div class="email"><div class="from"><div class="avatar">PL</div><div><strong>'+T('Purchasing team','Departamento de compras')+'</strong><small>'+E(r.customer)+(r.source==='whatsapp'?' · WhatsApp':' &lt;'+E(r.email)+'&gt;')+'</small></div></div><h2>'+T('Please quote the following items','Por favor, coticen estos productos')+'</h2><p>'+T('Hello, we need prices and availability for:','Hola, necesitamos precios y disponibilidad de:')+'</p><ul>'+r.original.map((i,k)=>'<li>'+itemDesc(i)+(r.unclear&&k===0?' - '+T('length to confirm','longitud por confirmar'):'')+' · '+i.qty+' '+UNIT(i.unit)+'</li>').join('')+'</ul><p>'+T('Please include delivery time, brand and quote validity.','Por favor, incluyan plazo de entrega, marca y vigencia de la cotización.')+'</p><div class="attachment">▤ '+E(r.fileName||('requirement-'+r.id.slice(-4)+'.'+(r.format.includes('PDF')?'pdf':r.format==='Excel'?'xlsx':r.format==='Word'?'docx':'txt')))+'</div></div><div class="actions"><span class="meta">'+T('Source reference retained for duplicate and revision checks.','Referencia conservada para detectar duplicados y revisiones.')+'</span>'+btn('Extract items','Extraer productos','extract')+'</div>';}else{html+=r.unclear&&!r.items[0]?.confirmed?'<div class="notice warn u-m16">'+T('One specification needs confirmation before supplier drafts can be created.','Falta confirmar una especificación antes de crear los borradores.')+'</div>':'';html+='<div class="table-wrap"><table><thead><tr><th>'+T('Line / product','Línea / producto')+'</th><th>'+T('Quantity','Cantidad')+'</th><th>'+T('Category','Categoría')+'</th><th>'+T('Review','Revisión')+'</th></tr></thead><tbody>'+r.items.map((i,k)=>'<tr><td><small>'+T('Original line','Línea original')+' '+(k+1)+'</small><input class="productinput '+(!i.confirmed?'invalid':'')+'" aria-label="'+T('Product description','Descripción del producto')+' '+(k+1)+'" data-edit="desc" data-id="'+i.id+'" value="'+E(L(i.desc))+'"></td><td><input type="number" min="1" step="1" data-edit="qty" data-id="'+i.id+'" aria-label="'+T('Quantity','Cantidad')+' '+(k+1)+'" value="'+i.qty+'"><small>'+UNIT(i.unit)+'</small></td><td><select data-edit="category" data-id="'+i.id+'" aria-label="'+T('Category','Categoría')+' '+(k+1)+'">'+CATS.map(c=>'<option value="'+c+'" '+(c===i.category?'selected':'')+'>'+CAT(c)+'</option>').join('')+'</select></td><td>'+(!i.confirmed?btn('Confirm spec','Confirmar dato','confirmSpec',i.id,true):badge(T('Reviewed','Revisado'),'good'))+'</td></tr>').join('')+'</tbody></table></div><div class="actions"><div class="toolbar">'+btn('Add line','Agregar producto','addline','',true)+btn('History matches','Consultar historial','page','history',true)+'</div>'+btn('Create supplier drafts →','Crear borradores →','createRFQs')+'</div>';}
html+='</div></section></div>';return html;}
function draftMessage(r,cat,ref){return T('Hello,','Hola,')+'\n\n'+T('Please quote the items below. Reference: ','Por favor, coticen estos productos. Referencia: ')+ref+'\n\n'+r.items.map((x,i)=>({...x,n:i+1})).filter(i=>i.category===cat&&!r.historyUsed[i.id]).map(i=>T('Line ','Línea ')+i.n+': '+L(i.desc)+' | '+i.qty+' '+UNIT(i.unit)).join('\n')+'\n\n'+T('Include unit price, currency, brand/origin, MOQ, delivery time and validity. Please use the attached Excel reply template.','Incluyan precio unitario, moneda, marca/origen, pedido mínimo, plazo de entrega y vigencia. Utilicen la plantilla de respuesta en Excel adjunta.')+'\n\n'+T('Thank you,\nPurchasing team','Gracias,\nDepartamento de compras');}
function renderRFQs(){const r=R();let html=heading(T('Supplier requests','Solicitudes a proveedores'),E(r.id+' · '+r.customer),requestPicker()+btn('Create / refresh drafts','Crear / actualizar borradores','createRFQs','',true));if(!r.extracted)return html+empty('Extract a request first','Primero extrae una solicitud','Review the customer requirements before contacting suppliers.','Revisa los requerimientos antes de contactar a los proveedores.',btn('Open request','Abrir solicitud','page','requests'));if(!r.rfqs.length&&r.items.every(i=>r.historyUsed[i.id]))return html+empty('Valid past prices selected','Precios históricos vigentes seleccionados','Every line uses a confirmed historical price. No new supplier requests are needed.','Todos los productos usan un precio histórico confirmado. No hace falta solicitar precios nuevos.',btn('Prepare customer quotation','Preparar cotización al cliente','page','quotes'));if(!r.rfqs.length)return html+empty('No supplier drafts','Sin borradores para proveedores','Create drafts from the reviewed product list, or reuse valid historical prices.','Crea borradores con los productos revisados o reutiliza precios históricos vigentes.',btn('Create drafts','Crear borradores','createRFQs'));html+='<div class="notice good">'+T('Customer identity, customer references and selling prices are excluded from supplier emails.','Los correos a proveedores excluyen la identidad del cliente, sus referencias y los precios de venta.')+'</div><div class="panel">';for(const q of r.rfqs){const applicable=suppliers.filter(s=>s.cat===q.category);html+='<div class="rfq"><div class="rfq-head"><div><h3>'+CAT(q.category)+'</h3><div class="meta">'+q.id+' · '+r.items.filter(i=>i.category===q.category&&!r.historyUsed[i.id]).length+' '+T('lines','productos')+'</div></div>'+badge(q.sent?T('Sent · awaiting replies','Enviada · esperando respuestas'):T('Draft · approval required','Borrador · requiere aprobación'),q.sent?'good':'warn')+'</div><div class="supplier-list">'+applicable.map(s=>'<label class="supplier-check"><input type="checkbox" data-supplier="'+q.id+'" value="'+s.id+'" '+(q.suppliers.includes(s.id)?'checked':'')+' '+(q.sent?'disabled':'')+'>'+E(s.name)+'<small class="meta">'+s.currency+'</small></label>').join('')+'</div><div class="draft"><div class="meta"><strong>CCO / Bcc:</strong> '+q.suppliers.map(id=>E(SUP(id).email)).join('; ')+'</div><div class="meta"><strong>'+T('Subject','Asunto')+':</strong> '+T('Supplier quotation request','Solicitud de cotización')+' · '+q.id+'</div><pre>'+E(draftMessage(r,q.category,q.id))+'</pre></div><div class="toolbar u-mt14">'+btn('Excel reply template ↓','Plantilla Excel ↓','xlsx',q.id,true)+(q.sent?btn('Send reminder','Enviar recordatorio','remind',q.id,true):btn('Approve & send','Aprobar y enviar','sendRFQ',q.id))+'<span class="meta">'+T('Reminders','Recordatorios')+': '+q.reminders+'</span></div></div>';}
return html+'</div><div class="toolbar u-end u-mt18">'+btn('Track replies & compare prices →','Ver respuestas y comparar →','page','replies')+'</div>';}
function renderReplies(){const r=R();let html=heading(T('Supplier replies & prices','Respuestas y precios'),E(r.id+' · '+r.customer),requestPicker()+btn('Record reply','Registrar respuesta','manualReply','',true)+btn('Import supplier replies','Importar respuestas de proveedores','importReplies'));if(!r.rfqs.some(q=>q.sent))return html+empty('Send supplier requests first','Primero envía las solicitudes','Approved supplier requests appear here for follow-up and comparison.','Las solicitudes aprobadas aparecen aquí para seguimiento y comparación.',btn('Open supplier drafts','Abrir borradores','page','rfqs'));let track=r.rfqs.filter(q=>q.sent).flatMap(q=>q.suppliers.map(sid=>({q,s:SUP(sid),count:r.offers.filter(o=>o.supplier===sid&&r.items.some(i=>i.id===o.line&&i.category===q.category)).length})));html+='<div class="panel"><div class="panel-head"><h2>'+T('Supplier follow-up','Seguimiento de proveedores')+'</h2><span class="meta">'+T('Reminder threshold: 24 hours','Recordatorio a las 24 horas')+'</span>'+btn('Run next-day reminders','Ejecutar recordatorios del día siguiente','followupCycle','',true)+'</div><div class="table-wrap"><table><thead><tr><th>'+T('Supplier','Proveedor')+'</th><th>RFQ</th><th>'+T('Reply','Respuesta')+'</th><th>'+T('Follow-up','Seguimiento')+'</th></tr></thead><tbody>'+track.map(({q,s,count})=>'<tr><td><strong>'+s.name+'</strong><small>'+s.email+'</small></td><td>'+q.id+'</td><td>'+badge(count?T('Received','Recibida'):T('Pending','Pendiente'),count?'good':'warn')+'</td><td>'+(!count?btn('Send reminder','Enviar recordatorio','remind',q.id,true):'<span class="meta">'+T('Recorded','Registrada')+'</span>')+' <small>'+q.reminders+' '+T('reminders logged','recordatorios registrados')+'</small></td></tr>').join('')+'</tbody></table></div></div>';
if(!r.offers.length)return html+'<div class="notice u-mt18">'+T('No replies recorded yet. Import supplier replies to compare offers.','Todavía no hay respuestas. Importa las respuestas de proveedores para comparar ofertas.')+'</div>';html+='<div class="notice u-mt19"><span>'+T('Prices normalized to OMR per unit, including configured supplier uplifts.','Precios convertidos a OMR por unidad, con los recargos configurados.')+' · AED × '+S.fx.AED+' · USD × '+S.fx.USD+'</span>'+btn('Use recommended offers','Usar ofertas recomendadas','recommend')+'</div>';
for(const i of r.items){const offers=r.offers.filter(o=>o.line===i.id);const chosen=currentOffer(r,i);html+='<div class="panel"><div class="panel-head"><div><h2>'+itemDesc(i)+'</h2><div class="meta">'+i.qty+' '+UNIT(i.unit)+' · '+CAT(i.category)+'</div></div>'+(chosen?badge(T('Supplier selected','Proveedor seleccionado'),'good'):badge(T('No price selected','Sin precio seleccionado'),'warn'))+'</div><div class="table-wrap"><table><thead><tr><th>'+T('Supplier / brand','Proveedor / marca')+'</th><th>'+T('Original price','Precio original')+'</th><th>'+T('Landed / unit','Costo / unidad')+'</th><th>'+T('Delivery','Entrega')+'</th><th>MOQ</th><th>'+T('Validity','Vigencia')+'</th><th>'+T('Checks','Revisión')+'</th><th></th></tr></thead><tbody>'+offers.map(o=>{const anomaly=norm(o)<(S.history[i.pid]?.[0]?.cost||norm(o))*.5||norm(o)>(S.history[i.pid]?.[0]?.cost||norm(o))*1.6;return '<tr class="'+(r.chosen[i.id]===o.id?'selected':'')+'"><td><strong>'+SUP(o.supplier).name+'</strong><small>'+E(o.brand)+' / '+E(o.origin)+'</small></td><td>'+money(o.price,o.currency)+'<small>'+T('Pack','Paquete')+': '+o.pack+' · +'+o.uplift+'%</small></td><td class="num"><strong>'+money(norm(o))+'</strong></td><td>'+o.lead+' '+T('days','días')+'</td><td>'+o.moq+'</td><td class="nowrap">'+date(o.valid)+'</td><td>'+(anomaly?badge(T('Price anomaly','Precio atípico'),'warn'):!eligible(o,i)?badge(!valid(o.valid)?T('Expired','Vencida'):T('MOQ not met','No alcanza mínimo'),'bad'):badge(T('Valid','Válida'),'good'))+(o.substitute?'<br>'+badge(T('Substitute brand','Marca sustituta'),'warn'):'')+'</td><td><button class="btn small '+(r.chosen[i.id]===o.id?'':'secondary')+'" data-action="chooseOffer" data-id="'+o.id+'" '+(!eligible(o,i)?'disabled':'')+'>'+T(r.chosen[i.id]===o.id?'Selected':'Select',r.chosen[i.id]===o.id?'Elegida':'Elegir')+'</button></td></tr>'}).join('')+(offers.length?'':'<tr><td colspan="8" class="meta">'+T('Awaiting supplier price.','Esperando precio del proveedor.')+'</td></tr>')+'</tbody></table></div></div>';}
return html+'<div class="toolbar u-end u-mt18">'+btn('Prepare customer quotation →','Preparar cotización al cliente →','page','quotes')+'</div>';}
function renderHistory(){const r=R();let html=heading(T('Price & quotation history','Historial de precios y cotizaciones'),T('Previous purchases, customer prices and similar product descriptions.','Compras anteriores, precios a clientes y productos similares.'),requestPicker()+btn('Import price history','Importar historial de precios','importHistory','',true));if(!r.extracted)return html+empty('Extract request items first','Primero extrae los productos','Historical matches are shown for each requested product.','El historial muestra coincidencias para cada producto solicitado.',btn('Open request','Abrir solicitud','page','requests'));html+='<div class="notice">'+T('Matches are ranked by description similarity. Confirm specifications before reusing a price.','Coincidencias ordenadas por similitud de descripción. Confirma las especificaciones antes de reutilizar un precio.')+'</div>';for(const i of r.items){const rows=(S.history[i.pid]||[]).slice(0,3);html+='<div class="panel"><div class="panel-head"><div><h2>'+itemDesc(i)+'</h2><div class="meta">'+T('Last purchase','Última compra')+': '+money(rows[0]?.cost)+' · '+T('Last price to this customer','Último precio a este cliente')+': '+(rows.find(h=>h.customer===r.customer)?money(rows.find(h=>h.customer===r.customer).sell):'-')+'</div></div>'+(r.historyUsed[i.id]?badge(T('Historical price in use','Precio histórico en uso'),'good'):'')+'</div><div class="table-wrap"><table><thead><tr><th>'+T('Closest descriptions','Descripciones similares')+'</th><th>'+T('Match','Coincidencia')+'</th><th>'+T('Purchased / quoted','Compra / venta')+'</th><th>'+T('Customer / outcome','Cliente / resultado')+'</th><th>'+T('Supplier validity','Vigencia del proveedor')+'</th><th></th></tr></thead><tbody>'+rows.map((h,k)=>'<tr class="'+(r.historyUsed[i.id]?.historyIndex===k?'history-highlight':'')+'"><td><strong>'+E(L(h.desc))+'</strong><small>'+SUP(h.supplier).name+' · '+date(h.date)+'</small></td><td>'+h.similarity+'%</td><td>'+money(h.cost)+' / '+money(h.sell)+'</td><td>'+E(h.customer)+'<small>'+outcomeLabel(h.outcome)+'</small></td><td>'+badge(date(h.valid),valid(h.valid)?'good':'bad')+'</td><td><button class="btn small secondary" data-action="useHistory" data-id="'+i.id+'|'+k+'" '+(!valid(h.valid)?'disabled':'')+'>'+T('Reuse price','Reutilizar precio')+'</button></td></tr>').join('')+'</tbody></table></div></div>';}
return html+'<div class="toolbar u-end u-mt18">'+btn('Return to supplier requests','Volver a proveedores','page','rfqs','true')+btn('Build customer quote →','Crear cotización →','page','quotes')+'</div>';}
function renderQuotes(){const r=R();let html=heading(T('Customer quotations','Cotizaciones a clientes'),E(r.id+' · '+r.customer),requestPicker()+btn('Pricing rules','Reglas de precios','settings','',true));if(!r.extracted)return html+empty('No products extracted','Sin productos extraídos','Open a request and review its products before pricing.','Abre una solicitud y revisa sus productos antes de cotizar.',btn('Open request','Abrir solicitud','page','requests'));let q=calcQuote(r);html+='<div class="panel"><div class="panel-body"><div class="settings-line"><label class="field">'+T('Customer type','Tipo de cliente')+'<select data-change="type"><option value="trade" '+(r.type==='trade'?'selected':'')+'>'+T('Trade customer','Cliente comercial')+'</option><option value="standard" '+(r.type==='standard'?'selected':'')+'>'+T('Standard customer (+3%)','Cliente general (+3%)')+'</option></select></label><label class="field">'+T('Credit terms','Plazo de crédito')+'<select data-change="credit">'+[0,30,60].map(n=>'<option value="'+n+'" '+(r.credit===n?'selected':'')+'>'+n+' '+T('days','días')+(n===60?' (+3%)':'')+'</option>').join('')+'</select></label><label class="field">'+T('Quote validity','Vigencia de la cotización')+'<input type="date" data-edit="validity" value="'+E(r.quoteUntil||q.until)+'" min="'+DAY+'" max="'+q.until+'"></label><span class="badge">'+T('Minimum margin','Margen mínimo')+': '+S.minMargin+'%</span></div></div><div class="table-wrap"><table><thead><tr><th>'+T('Include','Incluir')+'</th><th>'+T('Product / source','Producto / origen')+'</th><th>'+T('Qty','Cant.')+'</th><th>'+T('Unit cost','Costo unitario')+'</th><th>'+T('Margin %','Margen %')+'</th><th>'+T('Sell / unit','Venta / unidad')+'</th><th>'+T('Line total','Total')+'</th></tr></thead><tbody>'+r.items.map(i=>{let o=currentOffer(r,i),line=q.lines.find(x=>x.id===i.id),cost=o?(o.history?o.cost:norm(o)):null,margin=marginFor(r,i),price=r.overrides[i.id]?.price??(cost===null?0:cost/(1-margin/100));return '<tr><td><input type="checkbox" data-include="'+i.id+'" '+(r.include[i.id]!==false&&o?'checked':'')+' '+(!o?'disabled':'')+' aria-label="'+T('Include line','Incluir producto')+' '+i.id+'"></td><td><strong>'+itemDesc(i)+'</strong><small>'+(o?SUP(o.supplier).name+(o.history?' · '+T('History','Historial'):''):T('Awaiting price - excluded','Esperando precio - excluido'))+'</small></td><td>'+i.qty+'</td><td>'+ (cost===null?'-':money(cost))+'</td><td><input type="number" min="0" max="95" step="0.5" data-price="margin" data-id="'+i.id+'" aria-label="'+T('Margin','Margen')+' '+i.id+'" value="'+margin+'" '+(!o?'disabled':'')+'></td><td><input type="number" min="0.001" step="0.001" data-price="price" data-id="'+i.id+'" aria-label="'+T('Selling price','Precio de venta')+' '+i.id+'" value="'+price.toFixed(3)+'" '+(!o?'disabled':'')+'></td><td class="num" id="lineTotal-'+i.id+'">'+(line?money(line.total):'-')+'</td></tr>'}).join('')+'</tbody></table></div><div class="quote-summary"><div><div id="quoteWarnings"></div><div class="toolbar u-mt12">'+btn('Preview quotation','Vista previa','previewQuote')+btn('Save draft','Guardar borrador','saveQuote','',true)+'</div></div><div class="quote-total"><strong id="quoteTotal">'+money(q.total)+'</strong><small id="quoteMargin">'+T('Gross margin','Margen bruto')+': '+q.margin.toFixed(1)+'%</small></div></div></div><div id="exceptionPanel">'+exceptionUI(r,q)+'</div>';
html+='<div class="panel"><div class="panel-head"><h2>'+T('Customer email','Correo al cliente')+'</h2>'+badge(r.quote?.sent?T('Sent','Enviado'):T('Approval required','Requiere aprobación'),r.quote?.sent?'good':'warn')+'</div><div class="panel-body"><div class="meta">'+T('To','Para')+': '+E(r.email)+' · '+T('Customer reference','Referencia del cliente')+': '+E(r.reference)+'</div><div class="meta u-mt8">'+T('Attachment','Adjunto')+': '+(r.quote?.number||'QT-'+r.id.slice(-4))+'.pdf</div><p class="u-fs12">'+T('Please find our quotation attached. Let us know if you wish to proceed.','Adjuntamos nuestra cotización. Quedamos atentos a su confirmación.')+'</p><div class="toolbar">'+btn('Approve & send quote','Aprobar y enviar cotización','sendQuote')+btn('Print / save PDF','Imprimir / guardar PDF','printQuote','',true)+btn('Download quote HTML','Descargar cotización HTML','downloadQuote','',true)+'</div></div></div>';return html;}
function exceptionUI(r,q){const low=q.lines.some(l=>l.margin+1e-6<S.minMargin);if(!low)return '';return '<div class="notice warn u-mt18"><div>'+T('Some lines are below the minimum margin.','Hay productos por debajo del margen mínimo.')+' '+(r.exception?.approved?T('Exception approved.','Excepción aprobada.'):r.exception?.requested?T('Exception awaiting approval.','Excepción pendiente de aprobación.'):T('An approval exception is required.','Se requiere una excepción aprobada.'))+'</div>'+(r.exception?.approved?badge(T('Approved','Aprobada'),'good'):r.exception?.requested?btn('Approve exception','Aprobar excepción','approveException'):btn('Request exception','Solicitar excepción','requestException','',true))+'</div>';}
function refreshQuoteTotals(){const q=calcQuote(R());if(!$('quoteTotal'))return;$('quoteTotal').textContent=money(q.total);$('quoteMargin').textContent=T('Gross margin','Margen bruto')+': '+q.margin.toFixed(1)+'%';for(const i of R().items){const line=q.lines.find(l=>l.id===i.id);if($('lineTotal-'+i.id))$('lineTotal-'+i.id).textContent=line?money(line.total):'-'}$('quoteWarnings').innerHTML=(q.missing?badge(T('Partial quote','Cotización parcial')+' · '+q.missing+' '+T('lines excluded','productos excluidos'),'warn'):'')+' '+(!valid(q.until)?badge(T('Supplier price expired','Precio del proveedor vencido'),'bad'):'');$('exceptionPanel').innerHTML=exceptionUI(R(),q);}
function outcomeLabel(v){return ({won:T('Won','Ganada'),lost:T('Lost','Perdida'),noresponse:T('No response','Sin respuesta'),open:T('Open','Abierta')})[v]||v;}
function allQuotes(){const current=S.requests.filter(r=>r.quote).map(r=>{const q=r.quote;return {id:q.number,customer:r.customer,value:q.total,cost:q.cost,outcome:q.outcome||'open',turnaround:2.8,cat:r.items[0]?.category||'hardware',breakdown:q.lines.map(l=>({cat:l.category,value:l.total,cost:l.costTotal})),request:r.id}});return [...S.past,...current].filter(x=>reportFilter==='all'||x.outcome===reportFilter)}
function renderReports(){const r=R(),quotes=allQuotes(),won=quotes.filter(q=>q.outcome==='won'),lost=quotes.filter(q=>q.outcome==='lost'),rate=won.length+lost.length?won.length/(won.length+lost.length)*100:0,value=won.reduce((a,q)=>a+q.value,0),sum=quotes.reduce((a,q)=>a+q.value,0),cost=quotes.reduce((a,q)=>a+q.cost,0),totalSent=S.requests.reduce((a,r)=>a+r.rfqs.filter(q=>q.sent).length,0),suppliersSent=S.requests.reduce((a,r)=>a+r.rfqs.filter(q=>q.sent).reduce((n,q)=>n+q.suppliers.length,0),0),replied=S.requests.reduce((a,r)=>a+new Set(r.offers.map(o=>o.supplier)).size,0);let html=heading(T('Orders & reports','Pedidos e informes'),T('Quotation outcomes, incoming purchase orders and operating results.','Resultados de cotizaciones, órdenes de compra y operación.'),'<select data-change="reportFilter" aria-label="'+T('Outcome filter','Filtrar resultados')+'">'+['all','won','lost','noresponse','open'].map(v=>'<option value="'+v+'" '+(reportFilter===v?'selected':'')+'>'+ (v==='all'?T('All outcomes','Todos los resultados'):outcomeLabel(v))+'</option>').join('')+'</select>'+btn('Export report CSV','Exportar informe CSV','reportCSV','',true));html+='<div class="cards"><div class="metric"><label>'+T('Quotations','Cotizaciones')+'</label><strong>'+quotes.length+'</strong><small>'+S.requests.length+' '+T('current enquiries','solicitudes actuales')+'</small></div><div class="metric"><label>'+T('Won / decided','Ganadas / decididas')+'</label><strong>'+rate.toFixed(0)+'%</strong><small>'+won.length+' '+T('won','ganadas')+' / '+(won.length+lost.length)+' '+T('decided','decididas')+'</small></div><div class="metric"><label>'+T('Won order value','Valor de pedidos ganados')+'</label><strong>'+money(value)+'</strong><small>'+T('Before tax','Antes de impuestos')+'</small></div><div class="metric"><label>'+T('Quoted gross margin','Margen bruto cotizado')+'</label><strong>'+(sum?(sum-cost)/sum*100:0).toFixed(1)+'%</strong><small>'+T('Weighted by quoted revenue','Ponderado por importe cotizado')+'</small></div></div><div class="grid two"><div class="panel"><div class="panel-head"><h2>'+T('Incoming purchase order','Orden de compra entrante')+'</h2></div><div class="panel-body">'+requestPicker()+'<p class="meta">'+E(r.customer)+' · '+(r.quote?.number||T('No customer quotation yet','Todavía sin cotización'))+'</p>'+(r.po?'<div class="notice good">'+E(r.po.id)+' · '+T('Matched to','Vinculada a')+' '+E(r.quote.number)+' · '+money(r.po.total)+'</div>'+btn('Confirm order','Confirmar pedido','confirmOrder'):btn('Import & match PO','Importar y vincular OC','matchPO'))+'</div></div><div class="panel"><div class="panel-head"><h2>'+T('Operating results','Resultados operativos')+'</h2></div><div class="panel-body"><table><tbody><tr><td>'+T('Enquiries received','Solicitudes recibidas')+'</td><td class="num">'+S.requests.length+'</td></tr><tr><td>'+T('Average enquiry-to-quote time','Tiempo medio hasta cotizar')+'</td><td class="num">'+(quotes.length?quotes.reduce((a,q)=>a+q.turnaround,0)/quotes.length:0).toFixed(1)+' h</td></tr><tr><td>'+T('Supplier response rate','Respuesta de proveedores')+'</td><td class="num">'+(suppliersSent?Math.min(100,replied/suppliersSent*100).toFixed(0):0)+'% <small>'+replied+' / '+suppliersSent+'</small></td></tr><tr><td>'+T('Average supplier response','Tiempo medio de respuesta')+'</td><td class="num">'+(()=>{const os=S.requests.flatMap(x=>x.offers);return os.length?(os.reduce((n,o)=>n+(o.responseHours||0),0)/os.length).toFixed(1)+' h':'-'})()+'</td></tr><tr><td>'+T('Supplier RFQs sent','Solicitudes a proveedores enviadas')+'</td><td class="num">'+totalSent+'</td></tr></tbody></table></div></div></div><div class="panel"><div class="panel-head"><h2>'+T('Quotation register','Registro de cotizaciones')+'</h2></div><div class="table-wrap"><table><thead><tr><th>'+T('Quotation','Cotización')+'</th><th>'+T('Customer','Cliente')+'</th><th>'+T('Value','Importe')+'</th><th>'+T('Margin','Margen')+'</th><th>'+T('Outcome','Resultado')+'</th><th>'+T('Update','Actualizar')+'</th></tr></thead><tbody>'+quotes.map(q=>'<tr><td><strong>'+E(q.id)+'</strong></td><td>'+E(q.customer)+'</td><td>'+money(q.value)+'</td><td>'+(q.value?(q.value-q.cost)/q.value*100:0).toFixed(1)+'%</td><td>'+badge(outcomeLabel(q.outcome),q.outcome==='won'?'good':q.outcome==='lost'?'bad':'')+'</td><td><select data-outcome="'+E(q.id)+'" aria-label="'+T('Outcome','Resultado')+' '+E(q.id)+'">'+['open','won','lost','noresponse'].map(v=>'<option value="'+v+'" '+(v===q.outcome?'selected':'')+'>'+outcomeLabel(v)+'</option>').join('')+'</select></td></tr>').join('')+'</tbody></table></div></div><div class="grid two u-mt19">'+['category','customer'].map(group=>{let keys=group==='category'?CATS:[...new Set(quotes.map(q=>q.customer))];return '<div class="panel"><div class="panel-head"><h2>'+T('Margin by ','Margen por ')+(group==='category'?T('category','categoría'):T('customer','cliente'))+'</h2></div><div class="panel-body"><table><tbody>'+keys.map(k=>{let qs=quotes.filter(q=>group==='category'?(q.breakdown?q.breakdown.some(l=>l.cat===k):q.cat===k):q.customer===k),v=qs.reduce((a,q)=>a+(group==='category'&&q.breakdown?q.breakdown.filter(l=>l.cat===k).reduce((n,l)=>n+l.value,0):q.value),0),c=qs.reduce((a,q)=>a+(group==='category'&&q.breakdown?q.breakdown.filter(l=>l.cat===k).reduce((n,l)=>n+l.cost,0):q.cost),0);return '<tr><td>'+(group==='category'?CAT(k):E(k))+'</td><td class="num">'+money(v)+'</td><td class="num">'+(v?(v-c)/v*100:0).toFixed(1)+'%</td></tr>'}).join('')+'</tbody></table></div></div>'}).join('')+'</div>';return html;}
function openModal(title,body,buttonText,task,wide=false){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalSubmit').textContent=buttonText||T('Save','Guardar');$('modalSubmit').hidden=!task;$('modalCancel').textContent=T('Close','Cerrar');modalTask=task;$('modal').style.maxWidth=wide?'1000px':'760px';$('modal').showModal();}
function closeModal(){$('modal').close();modalTask=null;}
function field(label,name,value='',type='text',extra=''){return '<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+E(value)+'" '+extra+'></label>'}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function invalidate(r){r.rfqs=[];r.offers=[];r.chosen={};r.historyUsed={};r.overrides={};r.quote=null;r.po=null;r.exception=null;}
function extract(r){if(!r.extracted){r.items=r.original.map((i,k)=>({...structuredClone(i),confirmed:!(r.unclear&&k===0)}));r.extracted=true;log(r,'Products extracted for review','Productos extraídos para revisión');}r.showOriginal=false;render();}
function createRFQs(r){if(!r.extracted){toast(T('Extract and review the request first.','Primero extrae y revisa la solicitud.'));S.page='requests';render();return}if(r.items.some(i=>!L(i.desc).trim()||!i.confirmed||!Number.isInteger(i.qty)||i.qty<=0||!CATS.includes(i.category))){toast(T('Confirm specifications and enter positive whole quantities.','Confirma las especificaciones e introduce cantidades enteras positivas.'));S.page='requests';render();return}const cats=rfqGroups(r);r.rfqs=cats.map((c,k)=>r.rfqs.find(q=>q.category===c)||{id:'RFQ-'+r.id.slice(-4)+'-'+(k+1),category:c,suppliers:suppliers.filter(s=>s.cat===c).map(s=>s.id),sent:false,reminders:0});log(r,'Supplier drafts prepared','Borradores para proveedores preparados');S.page='rfqs';render();if(!cats.length)toast(T('All lines use historical prices; proceed to customer quotation.','Todos los productos usan precios históricos; continúa con la cotización.'));}
function addReplyFixtures(r){let rows=[];for(const i of r.items){for(const q of r.rfqs.filter(q=>q.sent&&q.category===i.category)){for(const sid of q.suppliers){const s=SUP(sid);let price;if(i.pid==='bolt')price=sid==='S101'?1.8:.195;else if(i.pid==='nut')price=sid==='S101'?.75:.085;else if(i.pid==='glove')price=sid==='S201'?2.8:1.15;else price=s.currency==='AED'?8:s.currency==='USD'?2.5:1;rows.push({id:r.id+'-'+i.id+'-'+sid,line:i.id,supplier:sid,price,currency:s.currency,pack:1,moq:sid==='S201'?24:1,lead:sid==='S101'?5:sid==='S201'?7:3,valid:sid==='S201'?'2026-11-10':'2026-11-25',brand:i.brand||'Standard',origin:sid==='S101'?'UAE':'Oman',uplift:s.uplift,substitute:false,responseHours:sid==='S101'?8:5})}}}for(const o of rows)if(!r.offers.find(v=>v.id===o.id))r.offers.push(o);log(r,'Supplier replies matched by RFQ and line','Respuestas vinculadas por solicitud y producto');render();toast(T('Replies recorded; currencies and units normalized.','Respuestas registradas; monedas y unidades normalizadas.'));}
function quotationDoc(r,q){let until=r.quoteUntil&&r.quoteUntil<=q.until?r.quoteUntil:q.until;return '<article class="doc"><div class="doc-head"><div><h2>MERIDIAN TRADING</h2><p>'+T('Industrial supplies · Sales department','Suministros industriales · Departamento de ventas')+'</p></div><div><strong>'+T('QUOTATION','COTIZACIÓN')+'</strong><p>'+(r.quote?.number||'QT-'+r.id.slice(-4))+'<br>'+date(DAY)+'</p></div></div><p><strong>'+E(r.customer)+'</strong><br>'+E(r.email)+'<br>'+T('Your reference','Su referencia')+': '+E(r.reference)+'</p><div class="table-wrap"><table><thead><tr><th>'+T('Description','Descripción')+'</th><th>'+T('Qty','Cant.')+'</th><th>'+T('Unit price','Precio unitario')+'</th><th class="num">'+T('Amount','Importe')+'</th></tr></thead><tbody>'+q.lines.map(i=>'<tr><td>'+itemDesc(i)+'</td><td>'+i.qty+' '+UNIT(i.unit)+'</td><td>'+money(i.price)+'</td><td class="num">'+money(i.total)+'</td></tr>').join('')+'</tbody></table></div><div class="doc-total">'+T('Total','Total')+': <strong>'+money(q.total)+'</strong></div><footer>'+T('Valid until','Vigente hasta')+': '+date(until)+' · '+T('Payment terms','Plazo de pago')+': '+r.credit+' '+T('days','días')+'<br>'+T('Delivery subject to supplier availability. Prices exclude tax.','Entrega sujeta a disponibilidad del proveedor. Precios sin impuestos.')+(q.missing?'<br>'+T('Partial quotation: remaining items will follow separately.','Cotización parcial: los productos restantes se cotizarán por separado.'):'')+'</footer></article>';}
function quoteErrors(r,q,approval=false){if(!q.lines.length)return T('Select at least one supplier price or reuse a historical price.','Elige al menos un precio de proveedor o reutiliza uno histórico.');if(q.lines.some(l=>l.price<=0||!Number.isFinite(l.price)||l.margin>=100))return T('Enter valid selling prices and margins below 100%.','Introduce precios válidos y márgenes inferiores al 100%.');if(q.lines.some(l=>!valid(l.valid)))return T('A selected supplier price has expired. Choose a valid price.','Un precio seleccionado ha vencido. Elige uno vigente.');if(r.quoteUntil&&(r.quoteUntil<DAY||r.quoteUntil>q.until))return T('Quote validity must fit within supplier validity.','La vigencia debe estar dentro de la vigencia del proveedor.');if(approval&&q.lines.some(l=>l.margin<S.minMargin)&&r.exception?.hash!==quoteHash(q))return T('Request and approve the minimum-margin exception first.','Primero solicita y aprueba la excepción de margen mínimo.');return '';}
const quoteHash=q=>JSON.stringify(q.lines.map(l=>[l.id,l.price,l.cost]));
function saveQuote(r,q){r.quote={...(r.quote||{}),number:'QT-'+r.id.slice(-4),total:q.total,cost:q.cost,lines:structuredClone(q.lines),valid:r.quoteUntil||q.until,outcome:r.quote?.outcome||'open',sent:r.quote?.sent||false};log(r,'Customer quotation saved','Cotización al cliente guardada');}
function importDialog(){const r=R();openModal(T('Import customer request','Importar solicitud del cliente'),'<div class="formgrid">'+field(T('Customer','Cliente'),'customer','New Customer','text','required')+field(T('Customer reference','Referencia del cliente'),'reference','CUST-NEW-'+(S.requests.length+1),'text','required')+'<label class="field">'+T('Message type','Tipo de mensaje')+'<select name="messageType"><option value="requirement">'+T('Customer requirement','Requerimiento del cliente')+'</option><option value="po">'+T('Purchase order','Orden de compra')+'</option><option value="reminder">'+T('Reminder','Recordatorio')+'</option><option value="general">'+T('General mail','Correo general')+'</option></select></label><label class="field">'+T('Source','Origen')+'<select name="source">'+['email','whatsapp','portal','upload','manual'].map(v=>'<option value="'+v+'">'+sourceName(v)+'</option>').join('')+'</select></label><label class="field">'+T('Document format','Formato del documento')+'<select name="format">'+['PDF','Scanned PDF','Excel','Word','Photo','Text'].map(v=>'<option>'+v+'</option>').join('')+'</select></label>'+field(T('File name','Nombre del archivo'),'fileName','customer-requirements.pdf')+'<label class="field">'+T('Requirements','Requerimientos')+'<select name="sample"><option value="standard">'+T('Bolts, nuts and gloves','Pernos, tuercas y guantes')+'</option><option value="unclear">'+T('Bolt length missing','Falta la longitud del perno')+'</option></select></label><label class="field full">'+T('Pasted requirement (optional)','Requerimiento pegado (opcional)')+'<textarea name="text" placeholder="'+T('200 pcs M10 bolts; 12 pairs gloves','200 pernos M10; 12 pares de guantes')+'"></textarea></label></div><p class="meta">'+T('Imported text is stored as a request note.','El texto importado se conserva como nota de la solicitud.')+'</p>',T('Import request','Importar solicitud'),data=>{if(data.get('messageType')!=='requirement'){S.intakeRecords||=[];S.intakeRecords.push({type:data.get('messageType'),reference:data.get('reference')});log(R(),'Non-enquiry classified and routed: '+data.get('messageType'),'Mensaje clasificado y enviado a su bandeja: '+data.get('messageType'));closeModal();render();toast(T('Message classified; no duplicate sales enquiry created.','Mensaje clasificado; no se creó una solicitud comercial.'));return;}const customer=String(data.get('customer')).trim(),ref=String(data.get('reference')).trim();if(S.requests.some(x=>x.customer.toLowerCase()===customer.toLowerCase()&&x.reference.toLowerCase()===ref.toLowerCase())){toast(T('Duplicate detected. Existing request retained.','Duplicado detectado. Se conserva la solicitud existente.'));closeModal();return}const id='ENQ-'+String(42+S.requests.length).padStart(4,'0'),n=makeRequest(id,customer,data.get('source'),data.get('format'),data.get('sample')==='unclear');n.reference=ref;n.fileName=String(data.get('fileName'));n.note=String(data.get('text')||'');if(n.unclear)n.original[0].desc={en:'SS hex bolt M10 - length unspecified',es:'Perno inoxidable M10 - longitud sin especificar'};S.requests.unshift(n);S.selected=n.id;S.page='requests';log(n,'Request imported','Solicitud importada');closeModal();render();});}
function settingsDialog(){openModal(T('Pricing & normalization settings','Precios y conversión'),'<div class="notice">'+T('Configured exchange rates. OMR is the comparison currency.','Tipos de cambio configurados. La comparación usa OMR.')+'</div><div class="formgrid">'+field('1 AED → OMR','AED',S.fx.AED,'number','step="0.0001" min="0.0001" required')+field('1 USD → OMR','USD',S.fx.USD,'number','step="0.0001" min="0.0001" required')+field(T('Base gross margin %','Margen bruto base %'),'base',S.baseMargin,'number','min="0" max="90" required')+field(T('Minimum margin %','Margen mínimo %'),'min',S.minMargin,'number','min="0" max="90" required')+'</div><p class="meta">'+T('Policy: safety category +5 points; standard customers +3; 60-day credit +3. Selling price = cost ÷ (1 − margin).','Reglas: seguridad industrial +5 puntos; clientes generales +3; crédito de 60 días +3. Precio = costo ÷ (1 − margen).')+'</p>',T('Apply settings','Aplicar configuración'),data=>{S.fx.AED=Number(data.get('AED'));S.fx.USD=Number(data.get('USD'));S.baseMargin=Number(data.get('base'));S.minMargin=Number(data.get('min'));S.requests.forEach(r=>{r.exception=null});save();closeModal();render();refreshQuoteTotals();});}
function manualReply(){const r=R();if(!r.items.length)return toast(T('Extract items first.','Primero extrae los productos.'));openModal(T('Record supplier reply','Registrar respuesta del proveedor'),'<div class="formgrid"><label class="field">'+T('Requested item','Producto solicitado')+'<select name="line">'+r.items.map(i=>'<option value="'+i.id+'">'+itemDesc(i)+'</option>').join('')+'</select></label><label class="field">'+T('Supplier','Proveedor')+'<select name="supplier">'+suppliers.map(s=>'<option value="'+s.id+'">'+s.name+'</option>').join('')+'</select></label>'+field(T('Quoted price','Precio cotizado'),'price',1,'number','min="0.0001" step="0.0001" required')+'<label class="field">'+T('Currency','Moneda')+'<select name="currency"><option>OMR</option><option>AED</option><option>USD</option></select></label>'+field(T('Units per quoted pack','Unidades por paquete cotizado'),'pack',1,'number','min="1" step="1" required')+field(T('Minimum order quantity','Pedido mínimo'),'moq',1,'number','min="1" step="1" required')+field(T('Delivery days','Días de entrega'),'lead',5,'number','min="0" required')+field(T('Valid until','Vigente hasta'),'valid','2026-11-25','date','required')+field(T('Brand / origin','Marca / origen'),'brand','A2 / UAE')+field(T('Landed-cost uplift %','Recargo de costo %'),'uplift',0,'number','min="0" max="100" required')+'<label class="supplier-check"><input type="checkbox" name="substitute">'+T('Substitute brand','Marca sustituta')+'</label></div>',T('Record reply','Registrar respuesta'),data=>{r.offers.push({id:'O-'+Date.now(),line:data.get('line'),supplier:data.get('supplier'),price:Number(data.get('price')),currency:data.get('currency'),pack:Number(data.get('pack')),moq:Number(data.get('moq')),lead:Number(data.get('lead')),valid:data.get('valid'),brand:data.get('brand'),origin:'-',uplift:Number(data.get('uplift')),substitute:data.has('substitute'),responseHours:6});log(r,'Supplier reply recorded manually','Respuesta de proveedor registrada manualmente');closeModal();render();});}
function action(name,id){if(name.startsWith('wa'))return whatsappAction(name,id);const r=R();switch(name){
case 'page':S.page=id;render();break;
case 'select':S.selected=id;render();break;
case 'extract':extract(r);break;
case 'source':r.showOriginal=true;render();break;
case 'import':importDialog();break;
case 'addsample':{const n=makeRequest('ENQ-'+String(42+S.requests.length).padStart(4,'0'),'Delta Engineering '+(S.requests.length+1),'email','Excel');S.requests.unshift(n);S.selected=n.id;log(n,'Enquiry received','Solicitud recibida');render();break;}
case 'duplicate':log(r,'Duplicate blocked: existing customer reference','Duplicado bloqueado: referencia de cliente existente');toast(T('Duplicate detected: no second request created.','Duplicado detectado: no se creó una segunda solicitud.'));break;
case 'revision':openModal(T('Import revised requirement','Importar requerimiento revisado'),'<p>'+T('The incoming document uses the same customer reference. Import it as the next revision? Existing prices and quotes will be cleared for review.','El documento usa la misma referencia del cliente. ¿Importarlo como una nueva versión? Se borrarán los precios y cotizaciones de esta solicitud para revisarla de nuevo.')+'</p><p><strong>'+E(r.reference)+' · v'+r.version+' → v'+(r.version+1)+'</strong></p>',T('Import revision','Importar revisión'),()=>{r.version++;r.original[0].qty+=20;r.extracted=false;r.items=[];invalidate(r);r.showOriginal=true;log(r,'Revised requirement imported; downstream work reset','Requerimiento revisado importado; se reinició el trabajo posterior');closeModal();render();});break;
case 'confirmSpec':{let i=r.items.find(x=>x.id===id);openModal(T('Confirm product specification','Confirmar especificación'),field(T('Confirmed description','Descripción confirmada'),'description',L(i.desc).replace(/ -.*$/,'')+' × 50 mm','text','required')+'<p class="meta">'+T('Use the description confirmed with the customer.','Usa la descripción confirmada con el cliente.')+'</p>',T('Confirm','Confirmar'),data=>{const v=String(data.get('description')).trim();if(!v||/unspecified|sin especificar/i.test(v))return toast(T('Enter the missing specification.','Introduce la especificación faltante.'));i.desc={en:v,es:v};i.confirmed=true;invalidate(r);log(r,'Product specification confirmed','Especificación del producto confirmada');closeModal();render();});break;}
case 'addline':openModal(T('Add requested product','Agregar producto solicitado'),'<div class="formgrid">'+field(T('Description','Descripción'),'description','','text','required')+field(T('Quantity','Cantidad'),'qty',1,'number','min="1" step="1" required')+'<label class="field">'+T('Category','Categoría')+'<select name="category">'+CATS.map(c=>'<option value="'+c+'">'+CAT(c)+'</option>').join('')+'</select></label><label class="field">'+T('Unit','Unidad')+'<select name="unit"><option value="pc">'+UNIT('pc')+'</option><option value="pair">'+UNIT('pair')+'</option></select></label></div>',T('Add product','Agregar producto'),data=>{invalidate(r);r.items.push({id:'L'+(r.items.length+1),pid:'custom',desc:{en:data.get('description'),es:data.get('description')},qty:Number(data.get('qty')),unit:data.get('unit'),category:data.get('category'),confirmed:true,brand:'Standard'});log(r,'Requested product added','Producto solicitado agregado');closeModal();render();});break;
case 'createRFQs':createRFQs(r);break;
case 'sendRFQ':{const q=r.rfqs.find(q=>q.id===id);if(!q.suppliers.length)return toast(T('Select at least one supplier.','Selecciona al menos un proveedor.'));q.sent=true;q.sentAt=Date.now();log(r,'Supplier request approved and sent: '+q.id,'Solicitud aprobada y enviada: '+q.id);render();toast(T('Supplier request marked as sent.','Solicitud marcada como enviada.'));break;}
case 'remind':{const q=r.rfqs.find(q=>q.id===id);q.reminders++;q.lastReminder=Date.now();log(r,'Supplier reminder sent: '+q.id,'Recordatorio enviado: '+q.id);render();toast(T('Reminder recorded.','Recordatorio registrado.'));break;}
case 'importReplies':if(!r.rfqs.some(q=>q.sent))return toast(T('Approve and send supplier requests first.','Primero aprueba y envía las solicitudes.'));addReplyFixtures(r);break;
case 'manualReply':manualReply();break;
case 'followupCycle':{let n=0;for(const q of r.rfqs.filter(q=>q.sent)){const pending=q.suppliers.filter(sid=>!r.offers.some(o=>o.supplier===sid&&r.items.some(i=>i.id===o.line&&i.category===q.category)));if(pending.length){q.reminders++;q.lastReminder=Date.now();n+=pending.length;log(r,'Scheduled reminder cycle: '+q.id,'Ciclo de recordatorios: '+q.id);}}render();toast(T('Follow-up cycle completed: ','Ciclo de seguimiento completado: ')+n+' '+T('pending suppliers reminded.','proveedores pendientes notificados.'));break;}
case 'recommend':{let n=0;for(const i of r.items){if(r.historyUsed[i.id])continue;const h=S.history[i.pid]?.[0]?.cost;const os=r.offers.filter(o=>o.line===i.id&&eligible(o,i)&&(!h||(norm(o)>=h*.5&&norm(o)<=h*1.6))&&!o.substitute).sort((a,b)=>norm(a)-norm(b));if(os[0]){r.chosen[i.id]=os[0].id;n++;}}r.exception=null;r.quote=null;r.po=null;log(r,'Recommended supplier prices selected','Precios recomendados seleccionados');render();toast(n+' '+T('supplier prices selected.','precios seleccionados.'));break;}
case 'chooseOffer':{const o=r.offers.find(o=>o.id===id),i=r.items.find(i=>i.id===o.line);if(!eligible(o,i))return;const history=S.history[i.pid]?.[0]?.cost;const flagged=o.substitute||(history&&(norm(o)<history*.5||norm(o)>history*1.6));const apply=()=>{r.chosen[o.line]=o.id;delete r.historyUsed[o.line];r.exception=null;r.quote=null;r.po=null;log(r,'Supplier selected: '+SUP(o.supplier).name,'Proveedor seleccionado: '+SUP(o.supplier).name);render();};if(flagged)openModal(T('Review flagged offer','Revisar oferta señalada'),'<p>'+T('This price differs substantially from history or uses a substitute brand. Confirm the specification before selecting it.','Este precio difiere del historial o usa una marca sustituta. Confirma la especificación antes de elegirlo.')+'</p>',T('Accept reviewed offer','Aceptar oferta revisada'),()=>{closeModal();apply()});else apply();break;}
case 'importHistory':if(!S.historyImported){S.history.bolt.splice(1,0,{desc:{en:'A2 hex bolt M10x50',es:'Perno hexagonal A2 M10x50'},supplier:'S102',cost:.185,sell:.255,customer:'Pacific Works',date:'2026-10-28',valid:'2026-11-22',outcome:'won',similarity:95});}S.historyImported=true;log(r,'Accounting and email history imported','Historial de contabilidad y correo importado');render();toast(T('Historical prices loaded; duplicate history records skipped.','Precios históricos cargados; registros duplicados omitidos.'));break;
case 'useHistory':{const [line,k]=id.split('|'),i=r.items.find(i=>i.id===line),h=S.history[i.pid][Number(k)];if(!valid(h.valid))return;if(!i.confirmed)return toast(T('Confirm the missing specification first.','Primero confirma la especificación faltante.'));openModal(T('Reuse historical supplier price','Reutilizar precio histórico'),'<p><strong>'+E(L(h.desc))+'</strong><br>'+SUP(h.supplier).name+' · '+money(h.cost)+' / '+UNIT(i.unit)+'</p><p>'+T('Confirm this is the same specification and that the supplier price remains valid. This line will be excluded from new supplier requests.','Confirma que la especificación coincide y que el precio sigue vigente. Este producto no se incluirá en nuevas solicitudes a proveedores.')+'</p><label class="supplier-check"><input type="checkbox" name="confirmed" required>'+T('Specifications and validity checked','Especificación y vigencia verificadas')+'</label>',T('Reuse price','Reutilizar precio'),()=>{r.historyUsed[line]={cost:h.cost,valid:h.valid,supplier:h.supplier,historyIndex:Number(k)};delete r.chosen[line];r.exception=null;r.quote=null;r.po=null;r.rfqs=[];log(r,'Historical price reused; RFQ skipped for '+line,'Precio histórico reutilizado; se omite solicitar '+line);closeModal();render();});break;}
case 'settings':settingsDialog();break;
case 'saveQuote':{const q=calcQuote(r),err=quoteErrors(r,q);if(err)return toast(err);saveQuote(r,q);render();refreshQuoteTotals();toast(T('Quotation draft saved.','Borrador guardado.'));break;}
case 'previewQuote':{const q=calcQuote(r),err=quoteErrors(r,q);if(err)return toast(err);openModal(T('Quotation preview','Vista previa de la cotización'),quotationDoc(r,q),null,null,true);break;}
case 'sendQuote':{const q=calcQuote(r),err=quoteErrors(r,q,true);if(err)return toast(err);openModal(T('Approve customer quotation','Aprobar cotización al cliente'),'<p><strong>'+E(r.customer)+'</strong><br>'+E(r.email)+'</p><p>'+T('Quotation total','Total de la cotización')+': <strong>'+money(q.total)+'</strong></p><p>'+T('Approve this quotation and record the outgoing customer email?','¿Aprobar esta cotización y registrar el correo saliente?')+'</p>',T('Approve & send','Aprobar y enviar'),()=>{saveQuote(r,q);r.quote.sent=true;r.quote.approvedAt=Date.now();log(r,'Customer quotation approved and sent','Cotización al cliente aprobada y enviada');closeModal();render();refreshQuoteTotals();});break;}
case 'requestException':openModal(T('Request pricing exception','Solicitar excepción de precio'),'<label class="field">'+T('Reason','Motivo')+'<textarea name="reason" required></textarea></label>',T('Request approval','Solicitar aprobación'),data=>{r.exception={requested:true,reason:data.get('reason'),pendingHash:quoteHash(calcQuote(r))};log(r,'Minimum-margin exception requested','Excepción de margen mínimo solicitada');closeModal();render();refreshQuoteTotals();});break;
case 'approveException':r.exception={...r.exception,approved:true,hash:quoteHash(calcQuote(r))};log(r,'Pricing exception approved by manager','Excepción de precio aprobada por el gerente');render();refreshQuoteTotals();break;
case 'printQuote':{const q=calcQuote(r),err=quoteErrors(r,q);if(err)return toast(err);$('printArea').innerHTML=quotationDoc(r,q);window.print();break;}
case 'downloadQuote':{const q=calcQuote(r),err=quoteErrors(r,q);if(err)return toast(err);download('QT-'+r.id.slice(-4)+'.html','<!doctype html><html lang="'+lang+'"><meta charset="utf-8"><title>QT-'+r.id.slice(-4)+'</title><style>'+[...document.styleSheets].flatMap(s=>[...s.cssRules]).map(r=>r.cssText).join('')+'</style><body><div id="printArea" style="display:block;max-width:900px;margin:30px auto;padding:25px;background:white">'+quotationDoc(r,q)+'</div></bo'+'dy></html>','text/html');break;}
case 'matchPO':if(!r.quote?.sent)return toast(T('Approve and send a customer quotation first.','Primero aprueba y envía una cotización al cliente.'));openModal(T('Match incoming purchase order','Vincular orden de compra entrante'),'<p><strong>PO-'+r.id.slice(-4)+'</strong> · '+E(r.customer)+'</p><table><tbody><tr><td>'+T('Quotation reference','Referencia de cotización')+'</td><td>'+r.quote.number+' ✓</td></tr><tr><td>'+T('Order amount','Importe del pedido')+'</td><td>'+money(r.quote.total)+' ✓</td></tr><tr><td>'+T('Products','Productos')+'</td><td>'+r.quote.lines.length+' ✓</td></tr></tbody></table>',T('Confirm match','Confirmar vínculo'),()=>{r.po={id:'PO-'+r.id.slice(-4),total:r.quote.total,quote:r.quote.number};log(r,'Incoming customer PO matched to quote','Orden de compra vinculada a la cotización');closeModal();render();});break;
case 'confirmOrder':if(!r.po)return;r.quote.outcome='won';log(r,'Customer order confirmed','Pedido del cliente confirmado');render();break;
case 'activity':openModal(T('Activity log','Registro de actividad'),'<ul class="timeline">'+(S.activity.length?S.activity.map(e=>'<li>'+E(L(e))+'<small>'+E(e.ref)+' · '+E(e.at)+'</small></li>').join(''):'<li>'+T('No activity recorded yet.','Todavía no hay actividad registrada.')+'</li>')+'</ul>',null,null);break;
case 'export':download('tradedesk-workspace.json',JSON.stringify(S,null,2),'application/json');break;
case 'reset':openModal(T('Reset workspace','Restablecer'),'<p>'+T('Reset this workspace to its initial data?','¿Restablecer este espacio de trabajo a sus datos iniciales?')+'</p>',T('Reset','Restablecer'),()=>{S=freshState();closeModal();render()});break;
case 'xlsx':downloadExcel(r,r.rfqs.find(q=>q.id===id));break;
case 'reportCSV':{const rows=[['Quotation','Customer','Amount OMR','Cost OMR','Outcome'],...allQuotes().map(q=>[q.id,q.customer,q.value.toFixed(3),q.cost.toFixed(3),q.outcome])];download('quotation-report.csv','\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');break;}
}}
