function waSampleItems(m){let items=structuredClone(productSeeds);if(m.sample==='bolts')items=[items[0]];if(m.sample==='gloves'){items=[items[2]];items[0].qty=36;}if(m.unclear){items=[items[0]];items[0].desc={en:'Stainless steel M10 bolt - length unspecified',es:'Perno inoxidable M10 - longitud sin especificar'};}return items;}
function whatsappAction(name,id){ensureWhatsApp();const c=WA();let m=id?c.messages.find(x=>x.id===id):waSelected(c);switch(name){
case 'waSelect':S.waSelected=id;WA().unread=0;render();break;
case 'waPick':if(m?.kind==='requirement'){c.selectedMessage=m.id;render();}break;
case 'waCreate':{if(!m||m.kind!=='requirement')return;let r=waLinked(c,m);if(r){S.selected=r.id;S.page='requests';render();toast(T('This message is already linked to a request.','Este mensaje ya está vinculado a una solicitud.'));return;}const max=Math.max(41,...S.requests.map(x=>Number(x.id.replace(/\D/g,''))||0));r=makeRequest('ENQ-'+String(max+1).padStart(4,'0'),c.company,'whatsapp',m.attachment?.type||'Text',Boolean(m.unclear));r.reference=m.id;r.sourceThreadId=c.id;r.sourceMessageId=m.id;r.contactName=c.name;r.contactPhone=c.phone;r.original=waSampleItems(m);r.note=waText(m);r.fileName=m.attachment?.name||'whatsapp-message.txt';r.whatsAppText=structuredClone(m.text);r.extracted=true;r.items=r.original.map((i,k)=>({...structuredClone(i),confirmed:!(m.unclear&&k===0)}));S.requests.unshift(r);S.selected=r.id;c.unread=0;log(r,'WhatsApp message converted to quotation request','Mensaje de WhatsApp convertido en solicitud de cotización');render();toast(T('Request created: ','Solicitud creada: ')+r.id);break;}
case 'waOpen':{const r=m&&waLinked(c,m);if(r){S.selected=r.id;S.page='requests';r.showOriginal=false;render();}break;}
case 'waAttachment':if(m?.attachment)openModal(m.attachment.name,'<div class="wa-attachment-preview"><div class="wa-file-icon">▤</div><h3>'+T('Customer requirement','Requerimiento del cliente')+'</h3><p>'+E(c.company)+'</p><ul>'+waSampleItems(m).map(i=>'<li>'+itemDesc(i)+' · '+i.qty+' '+UNIT(i.unit)+'</li>').join('')+'</ul><p class="meta">'+T('Attachment preview','Vista previa del archivo')+'</p></div>',null,null);break;
case 'waDraft':{const linked=waLinked(c,m);S.waDrafts||={};S.waDrafts[c.id]=m.unclear&&!m.resolved?T('Thank you, Carlos. Could you confirm the bolt length and required delivery date?','Gracias, Carlos. ¿Nos confirmas la longitud de los pernos y la fecha de entrega requerida?'):T('Thank you, '+c.name.split(' ')[0]+'. We received your request'+(linked?' ('+linked.id+')':'')+' and are checking prices and availability with our suppliers. We will send your quotation shortly.','Gracias, '+c.name.split(' ')[0]+'. Recibimos tu solicitud'+(linked?' ('+linked.id+')':'')+' y estamos revisando precios y disponibilidad con nuestros proveedores. Te enviaremos la cotización en breve.');render();$('waComposer').focus();break;}
case 'waSend':{const text=$('waComposer')?.value.trim();if(!text)return toast(T('Write a reply first.','Primero escribe una respuesta.'));c.messages.push({id:c.id+'-OUT-'+Date.now(),side:'out',time:new Date().toLocaleTimeString(lang==='es'?'es-MX':'en-GB',{hour:'2-digit',minute:'2-digit'}),text});S.waDrafts[c.id]='';const r=waLinked(c,waSelected(c));if(r)log(r,'WhatsApp customer reply recorded','Respuesta al cliente registrada en WhatsApp');save();render();$('waMessages').scrollTop=$('waMessages').scrollHeight;toast(T('Reply recorded.','Respuesta registrada.'));break;}
case 'waIncoming':{if(c.incomingAdded){toast(T('The follow-up is already in this conversation.','El seguimiento ya está en esta conversación.'));return;}c.incomingAdded=true;c.messages.push({id:c.id+'-FOLLOWUP',side:'in',time:'09:18',text:c.id==='WA-02'?{en:'Confirmed: M10 × 50 mm, please. We need delivery next week.',es:'Confirmado: M10 × 50 mm, por favor. Necesitamos la entrega la próxima semana.'}:{en:'Thank you. Please send the quotation here when it is ready.',es:'Gracias. Por favor, envíen la cotización por aquí cuando esté lista.'}});const selected=waSelected(c);if(c.id==='WA-02'){selected.resolved=true;selected.unclear=false;selected.text={en:'Please quote 200 stainless steel M10 × 50 mm bolts. Delivery needed next week.',es:'Por favor, coticen 200 pernos inoxidables M10 × 50 mm. Entrega la próxima semana.'};const r=waLinked(c,selected);if(r){r.unclear=false;r.original[0].desc={en:'Stainless steel hex bolt M10 × 50 mm',es:'Perno hexagonal inoxidable M10 × 50 mm'};if(r.items[0]){r.items[0].desc=structuredClone(r.original[0].desc);r.items[0].confirmed=true;}log(r,'Bolt length confirmed in WhatsApp','Longitud de perno confirmada en WhatsApp');}}c.unread=0;save();render();$('waMessages').scrollTop=$('waMessages').scrollHeight;break;}
}}

document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button&&!button.disabled){action(button.dataset.action,button.dataset.id||'');if(S.page==='quotes')refreshQuoteTotals();return}const language=e.target.closest('[data-language]');if(language){lang=language.dataset.language;render();if(S.page==='quotes')refreshQuoteTotals();}});
document.addEventListener('change',e=>{const el=e.target,r=R();if(el.dataset.change){switch(el.dataset.change){case 'request':S.selected=el.value;break;case 'requestFilter':requestFilter=el.value;break;case 'reportFilter':reportFilter=el.value;break;case 'type':r.type=el.value;markQuoteDirty(r);break;case 'credit':r.credit=Number(el.value);markQuoteDirty(r);break;}render();if(S.page==='quotes')refreshQuoteTotals();return}
if(el.dataset.edit){if(el.dataset.edit==='validity'){r.quoteUntil=el.value;markQuoteDirty(r);save();return}const i=r.items.find(i=>i.id===el.dataset.id);if(!i)return;invalidate(r);if(el.dataset.edit==='desc')i.desc={en:el.value,es:el.value};if(el.dataset.edit==='qty')i.qty=Number(el.value);if(el.dataset.edit==='category')i.category=el.value;save();return}
if(el.dataset.supplier){const q=r.rfqs.find(q=>q.id===el.dataset.supplier);if(q.sent)return;if(el.checked&&!q.suppliers.includes(el.value))q.suppliers.push(el.value);else if(!el.checked)q.suppliers=q.suppliers.filter(s=>s!==el.value);render();return}
if(el.dataset.include){r.include[el.dataset.include]=el.checked;markQuoteDirty(r);save();refreshQuoteTotals();return}
if(el.dataset.outcome){const q=S.past.find(q=>q.id===el.dataset.outcome);if(q)q.outcome=el.value;else{const rr=S.requests.find(rr=>rr.quote?.number===el.dataset.outcome);if(rr)rr.quote.outcome=el.value}save();render();return}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='waComposer'){S.waDrafts||={};S.waDrafts[S.waSelected]=el.value;save();return;}if(el.id==='waSearch'){filterWhatsApp(el.value);return;}if(!el.dataset.price)return;const r=R(),id=el.dataset.id,k=el.dataset.price;let v=Number(el.value);if(!Number.isFinite(v)||v<0||(k==='margin'&&v>=100)){el.setAttribute('aria-invalid','true');return}el.removeAttribute('aria-invalid');r.overrides[id]||={};r.overrides[id][k]=v;if(k==='margin'){delete r.overrides[id].price;let i=r.items.find(i=>i.id===id),o=currentOffer(r,i),cost=o.history?o.cost:norm(o);document.querySelector('[data-price="price"][data-id="'+id+'"]').value=(cost/(1-v/100)).toFixed(3)}else{let i=r.items.find(i=>i.id===id),o=currentOffer(r,i),cost=o.history?o.cost:norm(o);r.overrides[id].margin=v>0?(v-cost)/v*100:0;document.querySelector('[data-price="margin"][data-id="'+id+'"]').value=r.overrides[id].margin.toFixed(1)}markQuoteDirty(r);save();refreshQuoteTotals();});
